<?php if ( ! defined( 'ABSPATH' ) ) { exit; } if ( post_password_required() ) { return; } ?><section id="comments" class="comments-area reading-width"><?php if ( have_comments() ) : ?><h2><?php esc_html_e( 'Conversation', 'storypress' ); ?></h2><ol class="comment-list"><?php wp_list_comments( array( 'style' => 'ol', 'short_ping' => true, 'avatar_size' => 48 ) ); ?></ol><?php the_comments_navigation(); endif; if ( ! comments_open() && get_comments_number() ) : ?><p><?php esc_html_e( 'Comments are closed.', 'storypress' ); ?></p><?php endif; comment_form(); ?></section>
